useEffect(() => {
  if (!query.trim()) return;
  const ctrl = new AbortController();
  const t = setTimeout(() => {
    fetch(`/api/search?q=${encodeURIComponent(query)}`, { signal: ctrl.signal })
      .then(r => r.json())
      .then(setResults)
      .catch(e => e.name !== 'AbortError' && console.error(e));
  }, 300);
  return () => { clearTimeout(t); ctrl.abort(); };
}, [query]);
